const lockIssueForReviewGate = `-- name: LockIssueForReviewGate :one
SELECT id, workspace_id, title, description, status, priority, assignee_type, assignee_id, creator_type, creator_id, parent_issue_id, acceptance_criteria, context_refs, position, due_date, created_at, updated_at, number, project_id, origin_type, origin_id, first_executed_at, start_date, metadata, stage, properties, revision, last_activity_at FROM issue
WHERE id = $1 AND workspace_id = $2
FOR UPDATE
`

type LockIssueForReviewGateParams struct {
	ID          pgtype.UUID `json:"id"`
	WorkspaceID pgtype.UUID `json:"workspace_id"`
}

// Re-reads the issue under a row lock INSIDE the gate's transaction, so the
// status and project the decision rests on are the ones the write lands on.
//
// Without it the decision comes from a snapshot taken before the transaction
// opened, and "a filed workpaper refuses every write" is only true when nobody
// files it concurrently: a description edit could read 三级复核, be allowed,
// then block on the row lock and commit onto a workpaper that is now filed.
func (q *Queries) LockIssueForReviewGate(ctx context.Context, arg LockIssueForReviewGateParams) (Issue, error) {
	row := q.db.QueryRow(ctx, lockIssueForReviewGate, arg.ID, arg.WorkspaceID)
	var i Issue
	err := row.Scan(
		&i.ID,
		&i.WorkspaceID,
		&i.Title,
		&i.Description,
		&i.Status,
		&i.Priority,
		&i.AssigneeType,
		&i.AssigneeID,
		&i.CreatorType,
		&i.CreatorID,
		&i.ParentIssueID,
		&i.AcceptanceCriteria,
		&i.ContextRefs,
		&i.Position,
		&i.DueDate,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.Number,
		&i.ProjectID,
		&i.OriginType,
		&i.OriginID,
		&i.FirstExecutedAt,
		&i.StartDate,
		&i.Metadata,
		&i.Stage,
		&i.Properties,
		&i.Revision,
		&i.LastActivityAt,
	)
	return i, err
}

